(()=>{const form=document.querySelector('#contact-form');if(!form)return;const button=form.querySelector('button[type="submit"]'),status=document.querySelector('#form-status');const next=form.querySelector('[name="_next"]');if(next)next.value=new URL('/danke.html',window.location.origin).href;let sending=false;form.addEventListener('submit',async event=>{event.preventDefault();if(sending||!form.reportValidity())return;if(form.elements._honey.value)return;sending=true;button.disabled=true;button.textContent='Wird gesendet …';status.textContent='Deine Anfrage wird übermittelt.';form.setAttribute('aria-busy','true');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const response=await fetch('https://formsubmit.co/ajax/kontakt@sanscale.de',{method:'POST',body:new FormData(form),headers:{Accept:'application/json'},signal:controller.signal});const result=await response.json();if(!response.ok||!(result.success===true||result.success==='true'))throw new Error(/activation/i.test(result.message||'')?'activation':'submission failed');status.textContent='Danke! Du wirst zur Bestätigung weitergeleitet.';form.reset();window.location.assign('/danke.html')}catch(error){status.textContent=error.message==='activation'?'Der Formularversand ist noch nicht freigeschaltet. Bitte schreibe uns an kontakt@sanscale.de. Deine Eingaben bleiben erhalten.':'Der Versand konnte nicht bestätigt werden. Deine Eingaben bleiben erhalten. Bitte versuche es erneut oder schreibe an kontakt@sanscale.de.'}finally{clearTimeout(timer);sending=false;button.disabled=false;button.textContent='Projekt anfragen';form.removeAttribute('aria-busy')}})})();